package agent

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"testing"
	"time"

	"github.com/gorilla/websocket"
	forgeuisvc "github.com/viant/agently-core/service/primitiveprovider"
)

// The fixture is generated by Agently's landingWorkspaceSnapshot.test.js from
// actual Forge buildUISnapshot output. All records and chats are synthetic.
func TestLandingWorkspaceSnapshotReachesCurrentChatBootstrap(t *testing.T) {
	for _, file := range []string{"landing-workspace-snapshots.json", "adopted-window-snapshots.json"} {
		t.Run(file, func(t *testing.T) { verifyLandingWorkspaceBootstrap(t, file) })
	}
}

func verifyLandingWorkspaceBootstrap(t *testing.T, file string) {
	data, err := os.ReadFile("testdata/" + file)
	if err != nil {
		t.Fatal(err)
	}
	var fixture struct{ Baseline, Preserved map[string]interface{} }
	if err = json.Unmarshal(data, &fixture); err != nil {
		t.Fatal(err)
	}
	for _, test := range []struct {
		name, conversation string
		snapshot           map[string]interface{}
		wantProperties     bool
	}{
		{"previous-submit-focus", fixture.Baseline["conversationId"].(string), fixture.Baseline, false},
		{"preserved-first-submit", fixture.Preserved["conversationId"].(string), fixture.Preserved, true},
	} {
		t.Run(test.name, func(t *testing.T) {
			bridge := forgeuisvc.NewService(&forgeuisvc.Config{})
			server := httptest.NewServer(http.HandlerFunc(bridge.Hub().ServeWS))
			defer server.Close()
			connection, _, err := websocket.DefaultDialer.Dial("ws"+strings.TrimPrefix(server.URL, "http"), nil)
			if err != nil {
				t.Fatal(err)
			}
			defer connection.Close()
			if err = connection.WriteJSON(map[string]interface{}{"type": "ui.hello", "clientId": "landing-client"}); err != nil {
				t.Fatal(err)
			}
			if err = connection.WriteJSON(map[string]interface{}{"type": "ui.snapshot", "clientId": "landing-client", "data": test.snapshot}); err != nil {
				t.Fatal(err)
			}
			service := &Service{}
			service.SetUIBridge(bridge)
			var prompt string
			deadline := time.Now().Add(time.Second)
			for time.Now().Before(deadline) {
				prompt = service.workspaceUIBootstrap(context.Background(), test.conversation)
				if strings.Contains(prompt, "currentUIObservation") {
					break
				}
				time.Sleep(time.Millisecond)
			}
			if strings.Contains(prompt, `"tabId":"properties"`) != test.wantProperties {
				t.Fatalf("first-message UI context mismatch; properties=%v, prompt=%s", test.wantProperties, prompt)
			}
			selected := test.snapshot["selected"].(map[string]interface{})["windowId"].(string)
			if test.wantProperties && (!strings.Contains(prompt, `"windowId":"`+selected+`"`) || !strings.Contains(prompt, `"status":"active"`)) {
				t.Fatalf("preserved UI state missing from bootstrap: %s", prompt)
			}
			if test.wantProperties && file == "adopted-window-snapshots.json" {
				// The public semantic contract exposes scalar changed field names;
				// nested draft restoration is local and never becomes prompt data.
				for _, wanted := range []string{`"selectedIds":[7]`, `"dirty":true`, `"page":3`, `"changedFields":["name"]`} {
					if !strings.Contains(prompt, wanted) {
						t.Fatalf("freshly admitted restored state missing %s: %s", wanted, prompt)
					}
				}
			}
			for _, forbidden := range []string{"local-draft", "nested-draft", "baseline-2", "server-issued-fixture"} {
				if strings.Contains(prompt, forbidden) {
					t.Fatalf("raw local draft/row/proof leaked to LLM bootstrap: %s", forbidden)
				}
			}
			if other := service.workspaceUILiveSummaries(context.Background(), "unrelated-chat"); len(other) != 0 {
				t.Fatalf("workspace context leaked to another chat: %v", other)
			}
		})
	}
}
